// Transforma o evento do Google Chat (app HTTP) no formato da ponte do Core OS.
// Só MESSAGE vira pedido. ADDED_TO_SPACE responde boas-vindas; o resto é ignorado.
// Mapeie salas pra especialistas aqui: nome da sala (space.displayName) ou id (spaces/AAAA) → agente em .claude/agents/.
const SALA_AGENTE = {
  // 'SDR': 'sdr',
  // 'spaces/AAAAxxxxxxx': 'sdr',
};
const saida = [];
for (const item of $input.all()) {
  const b = item.json.body || item.json;
  // Chat API nova manda em b.chat.messagePayload; a antiga em b.message
  const ev = b.chat?.messagePayload || b;
  const tipo = b.type || (b.chat?.messagePayload ? 'MESSAGE' : b.chat?.addedToSpacePayload ? 'ADDED_TO_SPACE' : '');
  const msg = ev.message || {};
  const space = ev.space || msg.space || {};
  const user = (b.chat?.user) || ev.user || msg.sender || {};
  const texto = String(msg.argumentText ?? msg.text ?? '').trim();
  const thread = msg.thread?.name || '';
  const chave = thread || space.name || 'gchat';
  const agente = SALA_AGENTE[space.displayName] || SALA_AGENTE[space.name] || '';
  saida.push({ json: {
    tipo, texto, chave, agente,
    de: String(user.email || user.name || ''), nome: String(user.displayName || ''),
    space: space.name || '', spaceNome: space.displayName || '', thread, threadKey: thread.split('/').pop() || '',
    ack: tipo === 'ADDED_TO_SPACE' ? 'Oi! Sou o cérebro do Core OS. Me manda o que precisa; pra começar conversa nova, escreva /nova.' : '⏳',
  } });
}
return saida;
